const HIT_SOUND_DATA = "data:audio/mp3;base64,";

class SoundSynth {
  constructor() {
    this.ctx = null;
    this.hitAudio = null;
  }
  
  init() {
    if (!this.hitAudio) {
      try {
        this.hitAudio = new Audio(HIT_SOUND_DATA);
        this.hitAudio.preload = 'auto';
      } catch (e) {
        this.hitAudio = new Audio('sounds/hit.mp3');
      }
    }
    if (this.ctx) return;
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      this.ctx = new AudioCtx();
    } catch (e) {
      console.warn('Web Audio API not supported in this browser.');
    }
  }

  ensureContext() {
    if (!this.ctx) this.init();
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  playHit() {
    if (!State.sound) return;
    this.ensureContext();
    try {
      if (this.hitAudio) {
        const snd = this.hitAudio.cloneNode();
        snd.volume = Math.min(1, State.volume * 0.9);
        snd.play().catch(() => {});
      }
    } catch (e) {}
  }

  playHammer() {
    if (!State.sound) return;
    this.ensureContext();
    if (!this.ctx) return;
    
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(260, t);
    osc.frequency.exponentialRampToValueAtTime(45, t + 0.12);
    
    gain.gain.setValueAtTime(0.3 * State.volume, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
    
    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start(t);
    osc.stop(t + 0.13);
  }

  playBat() {
    if (!State.sound) return;
    this.ensureContext();
    if (!this.ctx) return;
    
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(440, t);
    osc.frequency.exponentialRampToValueAtTime(110, t + 0.18);
    
    gain.gain.setValueAtTime(0.35 * State.volume, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.18);
    
    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start(t);
    osc.stop(t + 0.19);
  }

  playBomb() {
    if (!State.sound) return;
    this.ensureContext();
    if (!this.ctx) return;
    
    const t = this.ctx.currentTime;
    
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(150, t);
    osc.frequency.exponentialRampToValueAtTime(25, t + 0.55);
    gain.gain.setValueAtTime(0.55 * State.volume, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.55);
    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start(t);
    osc.stop(t + 0.56);

    try {
      const bufferSize = this.ctx.sampleRate * 0.45;
      const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (this.ctx.sampleRate * 0.1));
      }
      const noise = this.ctx.createBufferSource();
      noise.buffer = buffer;
      const nGain = this.ctx.createGain();
      nGain.gain.setValueAtTime(0.4 * State.volume, t);
      nGain.gain.exponentialRampToValueAtTime(0.001, t + 0.45);
      noise.connect(nGain);
      nGain.connect(this.ctx.destination);
      noise.start(t);
    } catch (e) {}
  }

  playCombo(level) {
    if (!State.sound) return;
    this.ensureContext();
    if (!this.ctx) return;
    
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    
    const notes = [261.63, 293.66, 329.63, 392.00, 440.00, 523.25, 587.33, 659.25, 783.99];
    const freq = notes[Math.min(notes.length - 1, level)];
    
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, t);
    osc.frequency.exponentialRampToValueAtTime(freq * 1.5, t + 0.15);
    
    gain.gain.setValueAtTime(0.25 * State.volume, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.18);
    
    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start(t);
    osc.stop(t + 0.19);
  }

  playBossAlert() {
    if (!State.sound) return;
    this.ensureContext();
    if (!this.ctx) return;
    
    const t = this.ctx.currentTime;
    [180, 225].forEach((f, idx) => {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(f, t + idx * 0.12);
      gain.gain.setValueAtTime(0.3 * State.volume, t + idx * 0.12);
      gain.gain.exponentialRampToValueAtTime(0.001, t + idx * 0.12 + 0.35);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start(t + idx * 0.12);
      osc.stop(t + idx * 0.12 + 0.36);
    });
  }

  playVictory() {
    if (!State.sound) return;
    this.ensureContext();
    if (!this.ctx) return;
    
    const t = this.ctx.currentTime;
    const fan = [392, 523.25, 659.25, 783.99];
    fan.forEach((freq, idx) => {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(freq, t + idx * 0.1);
      gain.gain.setValueAtTime(0.25 * State.volume, t + idx * 0.1);
      gain.gain.exponentialRampToValueAtTime(0.001, t + idx * 0.1 + 0.3);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start(t + idx * 0.1);
      osc.stop(t + idx * 0.1 + 0.31);
    });
  }

  playPowerup() {
    if (!State.sound) return;
    this.ensureContext();
    if (!this.ctx) return;
    
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(320, t);
    osc.frequency.linearRampToValueAtTime(750, t + 0.22);
    gain.gain.setValueAtTime(0.25 * State.volume, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.22);
    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start(t);
    osc.stop(t + 0.23);
  }
}

const audio = new SoundSynth();
